#include "kira.h"
#include "memory.h"
uint32_t k9_crc(const uint8_t *p,size_t n){uint32_t c=~0u;size_t i;for(i=0;i<n;i++){unsigned j;c^=p[i];for(j=0;j<8;j++)c=(c>>1)^(0xEDB88320u & (0u-(c&1u)));}return ~c;}
static void put16(uint8_t *p,uint16_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8);}
static void put32(uint8_t *p,uint32_t v){put16(p,(uint16_t)v);put16(p+2,(uint16_t)(v>>16));}
static uint16_t get16(const uint8_t *p){return (uint16_t)(p[0]|(uint16_t)p[1]<<8);}
static uint32_t get32(const uint8_t *p){return get16(p)|(uint32_t)get16(p+2)<<16;}
int k9_song_validate(const k9_song *s){unsigned i;uint32_t end=0;if(!s||!s->count||s->count>K9_MAX_EVENTS||s->bpm<30||s->bpm>300||s->ticks>96u*60u*30u)return 0;for(i=0;i<s->count;i++){const k9_event *v=&s->events[i];if(!v->duration||v->tick<end||v->phone>=K9_NPHONE||v->note>127||v->velocity>127||v->stress>2||v->reserved)return 0;if(v->tick>s->ticks||v->duration>s->ticks-v->tick)return 0;end=v->tick+v->duration;if(end>s->ticks)return 0;}return 1;}
size_t k9_encode(const k9_song *s,uint8_t *o,size_t cap){unsigned i;size_t n;if(!k9_song_validate(s))return 0;n=24u+12u*s->count;if(cap<n)return 0;memset(o,0,n);memcpy(o,"K9S1",4);put16(o+4,1);put16(o+6,s->count);put16(o+8,s->bpm);put32(o+12,s->ticks);put32(o+16,(uint32_t)n);for(i=0;i<s->count;i++){const k9_event *v=&s->events[i];uint8_t *p=o+24+12*i;put32(p,v->tick);put16(p+4,v->duration);p[6]=v->phone;p[7]=v->note;p[8]=v->velocity;p[9]=v->stress;}put32(o+20,k9_crc(o+24,n-24));/* header checksum is folded into the payload CRC */put32(o+20,get32(o+20)^k9_crc(o,20));return n;}
int k9_decode(k9_song *dst,const uint8_t *in,size_t n){unsigned i;uint16_t count;if(n<24||n>K9_WIRE_MAX||memcmp(in,"K9S1",4)||get16(in+4)!=1||get16(in+10)||get32(in+16)!=n)return 0;count=get16(in+6);if(!count||count>K9_MAX_EVENTS||n!=24u+12u*count||get32(in+20)!=(k9_crc(in+24,n-24)^k9_crc(in,20)))return 0;/* Validate before touching caller's live song. */for(i=0;i<count;i++){const uint8_t *p=in+24+12*i;uint32_t end=get32(p)+get16(p+4);if(!get16(p+4)||end<get32(p)||p[6]>=K9_NPHONE||p[7]>127||p[8]>127||p[9]>2||get16(p+10)||end>get32(in+12)||(i&&get32(p)<get32(p-12)+get16(p-8)))return 0;}if(get16(in+8)<30||get16(in+8)>300||get32(in+12)>96u*60u*30u)return 0;memset(dst,0,sizeof(*dst));dst->count=count;dst->bpm=get16(in+8);dst->ticks=get32(in+12);for(i=0;i<count;i++){const uint8_t *p=in+24+12*i;k9_event *v=&dst->events[i];v->tick=get32(p);v->duration=get16(p+4);v->phone=p[6];v->note=p[7];v->velocity=p[8];v->stress=p[9];}return 1;}
